const headers = $input.item.json.headers || {};
const body = $input.item.json.body || {};

// Verify shared-secret authentication
const providedSecret = headers['x-webhook-secret'] || body.secret || '';
const expectedSecret = $env.CHAT_WEBHOOK_SECRET || 'secret_chat_handoff_123';

if (expectedSecret && providedSecret !== expectedSecret) {
  throw new Error("Unauthorized: Invalid X-Webhook-Secret header.");
}

const sessionId = body.sessionId || body.session_id || ('sess_' + Date.now());
const contactEmail = body.contactEmail || body.email || 'no-email@provided.com';
const contactName = body.contactName || body.name || 'Anonymous Visitor';
const query = body.query || body.userQuery || 'General escalation';
const reason = body.reason || 'Visitor requested human support or low confidence';

return {
  json: {
    session_id: sessionId,
    contact_email: contactEmail,
    contact_name: contactName,
    query: query,
    reason: reason,
    summary: `Customer inquiry: "${query}". Reason: ${reason}.`,
    created_at: new Date().toISOString()
  }
};

